import { TaskRelationType, type WorkProject, type WorkTask } from "../../types/work-projects"

/**
 * Richer tasks (P1): the task key shown as CODE#12, everyone on a task, the
 * links between tasks in both directions, and the small formatting used in
 * descriptions. Pure functions; the API and the screens use them.
 */

/** "ORB-01#12": the project code and the task's number in it. */
export function taskKey(task: Pick<WorkTask, "number">, project: Pick<WorkProject, "code"> | undefined) {
  return project && task.number ? `${project.code}#${task.number}` : ""
}

/** The next free number in a project. */
export function nextTaskNumber(tasks: Pick<WorkTask, "projectId" | "number">[], projectId: string) {
  return tasks.filter((t) => t.projectId === projectId).reduce((max, t) => Math.max(max, t.number ?? 0), 0) + 1
}

/** The main person first, then the others on the task; no repeats. */
export function taskPeople(task: Pick<WorkTask, "assigneeId" | "collaboratorIds">): string[] {
  return [...new Set([task.assigneeId, ...(task.collaboratorIds ?? [])].filter((x): x is string => !!x))]
}

export const isOnTask = (task: Pick<WorkTask, "assigneeId" | "collaboratorIds">, employeeId: string) => taskPeople(task).includes(employeeId)

export interface TaskLinks {
  /** Tasks this one waits for */
  blockedBy: WorkTask[]
  /** Tasks that wait for this one */
  blocks: WorkTask[]
  duplicates: WorkTask[]
  relates: WorkTask[]
}

/** How a task is tied to others, read from both sides (a relation set on either task counts). */
export function taskLinks(task: WorkTask, all: WorkTask[]): TaskLinks {
  const byId = (id: string) => all.find((t) => t.id === id)
  const both = (type: TaskRelationType) => {
    const ids = new Set([
      ...(task.relations ?? []).filter((r) => r.type === type).map((r) => r.taskId),
      ...all.filter((o) => o.id !== task.id && (o.relations ?? []).some((r) => r.type === type && r.taskId === task.id)).map((o) => o.id),
    ])
    return [...ids].map(byId).filter((t): t is WorkTask => !!t)
  }
  return {
    blockedBy: (task.dependsOn ?? []).map(byId).filter((t): t is WorkTask => !!t),
    blocks: all.filter((o) => o.dependsOn?.includes(task.id)),
    duplicates: both(TaskRelationType.DUPLICATE),
    relates: both(TaskRelationType.RELATES),
  }
}

/** Finds the task a key like "ORB-01#4" points at. */
export function findByKey(key: string, tasks: WorkTask[], projects: WorkProject[]): WorkTask | undefined {
  const m = key.match(/^(.+)#(\d+)$/)
  if (!m) return undefined
  const project = projects.find((p) => p.code.toLowerCase() === m[1]!.toLowerCase())
  return project ? tasks.find((t) => t.projectId === project.id && t.number === Number(m[2])) : undefined
}

export { isWebUrl } from "../utils/url"

// ---------- Formatting in descriptions ----------

/** A piece of formatted text: plain, **bold**, _italic_, `code`, [label](url), a bare URL, or a task key. */
export type Inline =
  | { kind: "text"; text: string }
  | { kind: "bold" | "italic" | "code"; text: string }
  | { kind: "link"; text: string; url: string }
  | { kind: "key"; text: string }

export type Block =
  | { kind: "paragraph"; inlines: Inline[] }
  | { kind: "heading"; inlines: Inline[] }
  | { kind: "bullets" | "numbers"; items: Inline[][] }
  | { kind: "checks"; items: { done: boolean; inlines: Inline[] }[] }

const INLINE = /(\*\*[^*\n]+\*\*|__[^_\n]+__|`[^`\n]+`|\[[^\]\n]+\]\(https?:\/\/[^)\s]+\)|https?:\/\/[^\s)]+|(?<![\w/])_[^_\n]+_(?!\w)|\b[A-Z][A-Z0-9]*(?:-[A-Z0-9]+)*#\d+\b)/g

export function parseInline(text: string): Inline[] {
  const out: Inline[] = []
  let last = 0
  for (const m of text.matchAll(INLINE)) {
    const token = m[0]
    if (m.index! > last) out.push({ kind: "text", text: text.slice(last, m.index) })
    if (token.startsWith("**") || token.startsWith("__")) out.push({ kind: "bold", text: token.slice(2, -2) })
    else if (token.startsWith("`")) out.push({ kind: "code", text: token.slice(1, -1) })
    else if (token.startsWith("[")) {
      const lm = token.match(/^\[([^\]]+)\]\((.+)\)$/)!
      out.push({ kind: "link", text: lm[1]!, url: lm[2]! })
    } else if (/^https?:\/\//.test(token)) out.push({ kind: "link", text: token, url: token })
    else if (token.startsWith("_")) out.push({ kind: "italic", text: token.slice(1, -1) })
    else out.push({ kind: "key", text: token })
    last = m.index! + token.length
  }
  if (last < text.length) out.push({ kind: "text", text: text.slice(last) })
  return out
}

/** Splits a description into blocks: paragraphs, # headings, - lists, 1. lists and [ ] checklists. */
export function parseRichText(source: string): Block[] {
  const blocks: Block[] = []
  const lines = source.replace(/\r\n?/g, "\n").split("\n")
  let para: string[] = []
  const flush = () => {
    if (para.length) blocks.push({ kind: "paragraph", inlines: parseInline(para.join(" ")) })
    para = []
  }
  for (const raw of lines) {
    const line = raw.trim()
    const check = line.match(/^[-*]\s+\[( |x|X)\]\s+(.*)$/)
    const bullet = line.match(/^[-*•]\s+(.*)$/)
    const number = line.match(/^\d+[.)]\s+(.*)$/)
    const heading = line.match(/^#{1,3}\s+(.*)$/)
    const prev = blocks[blocks.length - 1]
    if (!line) flush()
    else if (check) {
      flush()
      const item = { done: check[1] !== " ", inlines: parseInline(check[2]!) }
      if (prev?.kind === "checks") prev.items.push(item)
      else blocks.push({ kind: "checks", items: [item] })
    } else if (bullet || number) {
      flush()
      const kind = bullet ? "bullets" : "numbers"
      const inlines = parseInline((bullet ?? number)![1]!)
      if (prev?.kind === kind) prev.items.push(inlines)
      else blocks.push({ kind, items: [inlines] })
    } else if (heading) {
      flush()
      blocks.push({ kind: "heading", inlines: parseInline(heading[1]!) })
    } else para.push(line)
  }
  flush()
  return blocks
}
